def frogMinEnergyK(heights, k):
    n = len(heights)
    INF = float("inf")
    best = [0] + [INF] * (n - 1)
    for i in range(1, n):
        hi = heights[i]
        b = INF
        for j in range(max(0, i - k), i):
            c = best[j] + abs(hi - heights[j])
            if c < b:
                b = c
        best[i] = b
    return best[n - 1]
